SELECT  




        ( LIKE 
         OR  LIKE 
         OR  LIKE 
         OR  LIKE )

    AND c.ID_CIUDAD = #{f.idCiudad}
    AND d.ID_ZONA = #{f.idZona}
    AND d.PRECIO >= #{f.precioMin}
    AND d.PRECIO <= #{f.precioMax}
    AND d.CAPACIDAD >= #{f.huespedes}
    AND d.DORMITORIOS >= #{f.dormitorios}

        AND NOT EXISTS (
            SELECT 1 FROM RESERVAS r
            WHERE r.ID_DEPARTAMENTO = d.ID_DEPARTAMENTO
              AND r.ESTADO <> 'CANCELADA'
              AND r.FECHA_INICIO < #{f.salida}
              AND r.FECHA_FIN > #{f.llegada})



    ORDER BY d.PRECIO ASC NULLS LAST, d.ID_DEPARTAMENTO
    ORDER BY d.PRECIO DESC NULLS LAST, d.ID_DEPARTAMENTO
    ORDER BY d.FECHA_CREACION DESC, d.ID_DEPARTAMENTO DESC

LIMIT #{f.limite} OFFSET #{f.offset}

SELECT  
WHERE d.ID_ANFITRION = #{idAnfitrion}
ORDER BY d.FECHA_CREACION DESC
